import { useEffect, useState, type FormEvent, type ReactNode } from 'react'
import { ArrowRight, CircleAlert, Clock3, Droplets, ExternalLink, Filter, MapPin, Package, Plus, Search, ShieldCheck, ShoppingBag, Store, TriangleAlert } from 'lucide-react'
import { Link } from 'react-router-dom'
import { useDemo } from './state/DemoStore'
import { applyHumanDecision, activeReservationCount, activeReviews, availableStock, fulfillRequestAllocation, getRecommendation, makeIncident, pendingRequests, placePaidOrder, releaseRequestAllocation, stockTotals, unavailableStock, warehouseBlocked, warehouseInventory } from './domain/rules'
import type { Allocation, HelpRequest, ListingType, ProductListing, RequestStatus, ResourceCategory, Urgency } from './domain/models'

const categories: ResourceCategory[] = ['Water', 'Food', 'Hygiene', 'Medical', 'Emergency essentials']
const currency = (value: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value)
const dateLabel = (value: string) => new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }).format(new Date(value))
const makeId = (prefix: string) => `${prefix}-${crypto.randomUUID().slice(0, 8).toUpperCase()}`
const getOrganization = (state: ReturnType<typeof useDemo>['state'], id: string) => state.organizations.find(item => item.id === id)?.name || 'Community provider'
const getWarehouse = (state: ReturnType<typeof useDemo>['state'], id: string) => state.warehouses.find(item => item.id === id)

function Badge({ children }: { children: string }) {
  const text = children.toLowerCase()
  const tone = /critical|urgent|rejected|expired|blocked|shortage|failed/.test(text) ? 'red' : /pending|review|partial|high|paused|escalat|simulat|limited/.test(text) ? 'amber' : /free|available|active|approved|verified|accessible|fulfilled|ready|collected/.test(text) ? 'green' : 'neutral'
  return <span className={`badge badge--${tone}`}>{children}</span>
}

function PageTitle({ title, description, action }: { title: string; description: string; action?: ReactNode }) {
  return <div className="page-title"><div><h1>{title}</h1><p>{description}</p></div>{action}</div>
}

function DemoStrip({ children = 'Fictional records · local demo only' }: { children?: string }) {
  return <div className="demo-strip"><span className="demo-dot" />{children}</div>
}

function Metric({ label, value, note, href, icon: Icon }: { label: string; value: string | number; note: string; href: string; icon: typeof Package }) {
  return <Link className="metric" to={href}><div className="metric-top"><span>{label}</span><Icon size={17} /></div><strong>{value}</strong><small>{note}</small><ArrowRight className="metric-arrow" size={15} /></Link>
}

function Empty({ title, text, action }: { title: string; text: string; action?: ReactNode }) {
  return <div className="empty"><span className="empty-icon"><Package size={19} /></span><strong>{title}</strong><p>{text}</p>{action}</div>
}

function audit(state: ReturnType<typeof useDemo>['state'], action: string, detail: string) {
  return { id: makeId('AUD'), action, actor: state.currentUser.name, detail, createdAt: new Date().toISOString() }
}

export function Overview() {
  const { state } = useDemo()
  const totals = stockTotals(state)
  const pending = pendingRequests(state)
  const awaitingOrders = state.orders.filter(order => order.status !== 'Collected' && order.status !== 'Cancelled')
  const shortages = pending.filter(request => getRecommendation(state, request).shortage > 0)
  const accessibleWarehouses = state.warehouses.filter(warehouse => warehouse.accessible && !warehouseBlocked(state, warehouse.id)).length
  const activeListings = state.listings.filter(listing => listing.status === 'Active')
  const freeListings = activeListings.filter(listing => listing.listingType === 'FREE' && availableStock(state, listing) > 0).length
  const lowStockListings = activeListings.filter(listing => availableStock(state, listing) > 0 && availableStock(state, listing) <= 10)
  const urgent = pending.filter(request => request.urgency === 'Critical').slice(0, 3)
  const categorySupply = categories.map(category => ({ category, quantity: state.listings.filter(item => item.category === category && availableStock(state, item) > 0).length }))
  const maxSupply = Math.max(1, ...categorySupply.map(item => item.quantity))
  return <div className="page-stack">
    <PageTitle title="Good morning, Alex" description="A clear picture of essential resources and the decisions waiting for your team." action={<Link to="/reviews" className="button button--primary"><ShieldCheck size={16} />Review allocations</Link>} />
    <DemoStrip />
    <section className="metric-grid" aria-label="Live demo overview metrics">
      <Metric label="Active listings" value={activeListings.length} note="Across all resource categories" href="/listings" icon={Store} />
       <Metric label="Free resources available" value={freeListings} note={`${totals.free.toLocaleString('en-IN')} stock units across listings`} href="/resources?type=FREE" icon={Package} />
      <Metric label="Reviews waiting" value={activeReviews(state).length} note="Coordinator decision required" href="/reviews" icon={ShieldCheck} />
      <Metric label="Orders to fulfill" value={awaitingOrders.length} note="Simulated pickup orders" href="/orders" icon={ShoppingBag} />
    </section>
    <section className="metric-grid metric-grid--compact" aria-label="Additional overview metrics">
      <Link className="mini-metric" to="/resources?type=PAID"><span>Affordable paid products</span><strong>{state.listings.filter(item => item.status === 'Active' && item.listingType === 'PAID' && availableStock(state, item) > 0).length}</strong></Link>
      <Link className="mini-metric" to="/requests"><span>Requests needing attention</span><strong>{pending.length}</strong></Link>
      <Link className="mini-metric" to="/simulator"><span>Potential shortages</span><strong className={shortages.length ? 'value-warning' : ''}>{shortages.length}</strong></Link>
      <Link className="mini-metric" to="/listings"><span>Low stock listings</span><strong className={lowStockListings.length ? 'value-warning' : ''}>{lowStockListings.length}</strong></Link>
      <Link className="mini-metric" to="/warehouses"><span>Accessible locations</span><strong>{accessibleWarehouses} <small>of {state.warehouses.length}</small></strong></Link>
    </section>
    <div className="content-grid">
      <section className="panel">
        <div className="section-head"><div><h2>Urgent requests</h2><p>Prioritize critical needs for coordinator review.</p></div><Link to="/requests" className="text-link">All requests <ArrowRight size={14} /></Link></div>
        <div className="record-list">{urgent.length ? urgent.map(request => <Link to="/reviews" key={request.id} className="record-row"><span className="record-symbol record-symbol--red"><TriangleAlert size={17} /></span><span className="record-main"><strong>{request.resourceName}</strong><small>{request.requester} · {request.location}</small></span><span className="record-quantity">{request.quantity - request.allocatedQuantity} {request.unit}</span><Badge>{request.urgency}</Badge></Link>) : <Empty title="No critical requests" text="Critical requests will appear here when submitted." />}</div>
      </section>
      <section className="panel">
        <div className="section-head"><div><h2>Resource availability</h2><p>Active listings by category · accessible stock only.</p></div><Link to="/resources" className="text-link">Browse <ArrowRight size={14} /></Link></div>
        <div className="supply-chart">{categorySupply.map(item => <div className="supply-row" key={item.category}><div className="supply-label"><span>{item.category}</span><strong>{item.quantity.toLocaleString('en-IN')}</strong></div><div className="supply-track"><span style={{ width: `${Math.max(item.quantity > 0 ? 3 : 0, item.quantity / maxSupply * 100)}%` }} /></div></div>)}</div>
        <div className="chart-note"><Droplets size={15} /> A listing counts only while eligible stock is accessible and in date.</div>
      </section>
    </div>
    <div className="content-grid">
      <section className="panel"><div className="section-head"><div><h2>Needs attention</h2><p>Requests with less eligible free stock than requested.</p></div><Link to="/simulator" className="text-link">Shortage view <ArrowRight size={14} /></Link></div>
        {shortages.length ? <div className="record-list">{shortages.slice(0, 4).map(request => { const match = getRecommendation(state, request); return <Link className="record-row" to="/reviews" key={request.id}><span className="record-symbol record-symbol--amber"><CircleAlert size={17} /></span><span className="record-main"><strong>{request.resourceName}</strong><small>{request.id} · {match.availableQuantity} available, {match.shortage} short</small></span><Badge>{request.status}</Badge></Link> })}</div> : <div className="quiet-state">No current request has a stock shortage.</div>}
        {lowStockListings.length > 0 && <div className="low-stock-block"><div className="low-stock-heading"><strong>Low stock watch</strong><span>10 or fewer eligible units remaining</span></div>{lowStockListings.map(listing => <div className="record-row" key={listing.id}><span className="record-symbol record-symbol--amber"><TriangleAlert size={16} /></span><span className="record-main"><strong>{listing.name}</strong><small>{getWarehouse(state, listing.warehouseId)?.name} · {getOrganization(state, listing.providerId)}</small></span><span className="record-quantity">{availableStock(state, listing)} {listing.unit}</span></div>)}</div>}
      </section>
      <section className="panel"><div className="section-head"><div><h2>Recent activity</h2><p>Latest state changes across this demo.</p></div><Link to="/activity" className="text-link">Audit log <ArrowRight size={14} /></Link></div>
        <div className="activity-list">{state.audit.slice(0, 4).map(event => <div className="activity-row" key={event.id}><span className="activity-dot"><Clock3 size={14} /></span><span><strong>{event.action}</strong><small>{event.detail}</small></span><time>{dateLabel(event.createdAt)}</time></div>)}</div>
      </section>
    </div>
  </div>
}

export function FindResources() {
  const { state, setState } = useDemo()
  const params = new URLSearchParams(window.location.search)
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState('All categories')
  const [type, setType] = useState(params.get('type') || 'All listings')
  const [availability, setAvailability] = useState('Available stock')
  const [warehouseId, setWarehouseId] = useState('All locations')
  const [maxPrice, setMaxPrice] = useState('')
  const [sort, setSort] = useState('Recommended')
  const [selectedId, setSelectedId] = useState('')
  const selected = state.listings.find(item => item.id === selectedId) || null
  const [quantity, setQuantity] = useState(1)
  const [location, setLocation] = useState('')
  const [urgency, setUrgency] = useState<Urgency>('High')
  const [message, setMessage] = useState('')
  const listings = state.listings.filter(item => item.status === 'Active' && (availability === 'All active' || (availability === 'Available stock' ? availableStock(state, item) > 0 : availableStock(state, item) === 0)) && (!query || `${item.name} ${getOrganization(state, item.providerId)} ${getWarehouse(state, item.warehouseId)?.name || ''} ${getWarehouse(state, item.warehouseId)?.address || ''}`.toLowerCase().includes(query.toLowerCase())) && (category === 'All categories' || item.category === category) && (type === 'All listings' || item.listingType === type) && (warehouseId === 'All locations' || item.warehouseId === warehouseId) && (!maxPrice || item.listingType === 'FREE' || item.priceInr <= Number(maxPrice)))
  const sorted = [...listings].sort((a, b) => sort === 'Lowest price' ? a.priceInr - b.priceInr : sort === 'Most available' ? availableStock(state, b) - availableStock(state, a) : Number(a.listingType === 'PAID') - Number(b.listingType === 'PAID'))
  const choose = (listing: ProductListing) => { setSelectedId(listing.id); setQuantity(1); setMessage('') }
  const submit = (event: FormEvent) => {
    event.preventDefault()
    if (!selected || !Number.isInteger(quantity) || quantity < 1 || quantity > availableStock(state, selected)) { setMessage('Choose a whole-number quantity within the currently available stock.'); return }
    if (selected.listingType === 'FREE') {
      if (location.trim().length < 2) { setMessage('Add a pickup area so the coordinator can review your request.'); return }
      const request: HelpRequest = { id: makeId('REQ'), requester: state.role === 'Taker' ? 'Demo community member' : 'Demo requestor', category: selected.category, resourceName: selected.name, quantity, unit: selected.unit, urgency, location: location.trim(), createdAt: new Date().toISOString(), status: 'Under Review', notes: `Free assistance request for ${selected.id}. Coordinator review required.`, allocatedQuantity: 0 }
      setState(current => ({ ...current, requests: [request, ...current.requests], audit: [audit(current, 'Free assistance requested', `${request.id} · ${quantity} ${selected.unit} of ${selected.name}`), ...current.audit] }))
      setMessage(`Request ${request.id} submitted for coordinator review. No stock was reserved yet.`)
    } else {
      try {
        const total = selected.priceInr * quantity
        setState(placePaidOrder(state, selected.id, quantity))
        setMessage(`Order placed for ${currency(total)}. This is a demo order; no payment was collected.`)
      } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not place this order.') }
    }
  }
  return <div className="page-stack">
    <PageTitle title="Find resources" description="Browse free community donations and clearly priced surplus. Free and paid options are kept separate." />
    <DemoStrip>Fictional listings · pickup stock is not live</DemoStrip>
    <div className="filter-bar"><label className="search-field"><Search size={17} /><input aria-label="Search products, providers, and pickup locations" placeholder="Search products, providers, locations" value={query} onChange={event => setQuery(event.target.value)} /></label><label><span className="sr-only">Category</span><select value={category} onChange={event => setCategory(event.target.value)}><option>All categories</option>{categories.map(item => <option key={item}>{item}</option>)}</select></label><label><span className="sr-only">Listing type</span><select value={type} onChange={event => setType(event.target.value)}><option>All listings</option><option>FREE</option><option>PAID</option></select></label><label><span className="sr-only">Availability</span><select value={availability} onChange={event => setAvailability(event.target.value)}><option>Available stock</option><option>Unavailable stock</option><option>All active</option></select></label><label><span className="sr-only">Pickup location</span><select value={warehouseId} onChange={event => setWarehouseId(event.target.value)}><option>All locations</option>{state.warehouses.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label><span className="sr-only">Maximum price</span><input className="price-filter" type="number" min="0" placeholder="Max ₹" value={maxPrice} onChange={event => setMaxPrice(event.target.value)} /></label><label><span className="sr-only">Sort</span><select value={sort} onChange={event => setSort(event.target.value)}><option>Recommended</option><option>Lowest price</option><option>Most available</option></select></label><span className="filter-count"><Filter size={14} />{sorted.length} results</span></div>
    {message && <div role="status" className="inline-message">{message}</div>}
    <div className="resource-layout"><div className="resource-grid-list">{sorted.length ? sorted.map(listing => { const warehouse = getWarehouse(state, listing.warehouseId); const available = availableStock(state, listing); return <article className="resource-card" key={listing.id}><div className="resource-card-top"><span className={`type-label type-label--${listing.listingType.toLowerCase()}`}>{listing.listingType === 'FREE' ? 'FREE · DONATION' : 'PAID · SURPLUS'}</span><div className="badge-group"><Badge>{listing.category}</Badge>{available === 0 && <Badge>Unavailable</Badge>}</div></div><h2>{listing.name}</h2><p>{listing.description}</p><div className="resource-card-meta"><span><MapPin size={14} />{warehouse?.name || 'Pickup details pending'}</span><span>{getOrganization(state, listing.providerId)}</span></div><div className="resource-card-bottom"><div><strong>{listing.listingType === 'FREE' ? 'Free' : `${currency(listing.priceInr)} / ${listing.unit}`}</strong><small>{available.toLocaleString('en-IN')} {listing.unit} available</small></div><button className="button button--secondary" disabled={available === 0} onClick={() => choose(listing)}>{available === 0 ? 'Unavailable' : listing.listingType === 'FREE' ? 'Request free' : 'View & order'}<ArrowRight size={15} /></button></div></article> }) : <Empty title="No listings match these filters" text="Try a different category, availability, pickup location, or price limit." action={<button className="button button--secondary" onClick={() => { setQuery(''); setCategory('All categories'); setType('All listings'); setAvailability('Available stock'); setWarehouseId('All locations'); setMaxPrice('') }}>Clear filters</button>} />}</div>
      {selected && <section className="panel action-panel" aria-label="Selected resource action"><button className="panel-close" onClick={() => setSelectedId('')} aria-label="Close resource details">×</button><span className={`type-label type-label--${selected.listingType.toLowerCase()}`}>{selected.listingType}</span><h2>{selected.name}</h2><p className="muted">{selected.description}</p><dl className="detail-list"><div><dt>Provider</dt><dd>{getOrganization(state, selected.providerId)}</dd></div><div><dt>Pickup</dt><dd>{getWarehouse(state, selected.warehouseId)?.name}</dd></div><div><dt>Available</dt><dd>{availableStock(state, selected).toLocaleString('en-IN')} {selected.unit}</dd></div>{selected.bestBefore && <div><dt>Best before</dt><dd>{new Date(selected.bestBefore).toLocaleDateString('en-IN')}</dd></div>}</dl><form onSubmit={submit} className="stack-form"><label>Quantity ({selected.unit})<input type="number" min="1" max={availableStock(state, selected)} value={quantity} onChange={event => setQuantity(Number(event.target.value))} required /></label>{selected.listingType === 'FREE' ? <><label>Pickup area<input value={location} onChange={event => setLocation(event.target.value)} placeholder="Your area or landmark" required /></label><label>Urgency<select value={urgency} onChange={event => setUrgency(event.target.value as Urgency)}><option>Routine</option><option>High</option><option>Critical</option></select></label><p className="helper-text">This creates an assistance request. Stock is not reserved until a coordinator approves an allocation.</p><button className="button button--primary" type="submit">Submit free request</button></> : <><div className="order-total"><span>Total · {quantity} × {currency(selected.priceInr)}</span><strong>{currency(selected.priceInr * quantity)}</strong></div><p className="helper-text">Simulated order only. No payment credentials or payment will be requested.</p><button className="button button--primary" type="submit">Place demo order</button></>}</form></section>}
    </div>
  </div>
}

export function Requests() {
  const { state, setState } = useDemo()
  const [showForm, setShowForm] = useState(false)
  const [selected, setSelected] = useState<string | null>(null)
  const [statusFilter, setStatusFilter] = useState('All statuses')
  const [form, setForm] = useState({ requester: '', category: 'Water' as ResourceCategory, resourceName: '', quantity: '1', unit: 'units', urgency: 'High' as Urgency, location: '', notes: '' })
  const [message, setMessage] = useState('')
  const [fulfillmentNote, setFulfillmentNote] = useState('')
  const rows = state.requests.filter(item => statusFilter === 'All statuses' || item.status === statusFilter).sort((a, b) => b.createdAt.localeCompare(a.createdAt))
  const submit = (event: FormEvent) => {
    event.preventDefault()
    const quantity = Number(form.quantity)
    if (!Number.isInteger(quantity) || quantity <= 0) { setMessage('Quantity must be a positive whole number.'); return }
    const resourceName = form.resourceName.trim(), unit = form.unit.trim(), location = form.location.trim()
    if (!resourceName || !unit || !location) { setMessage('Enter the resource, unit, and pickup area without leaving them blank.'); return }
    const request: HelpRequest = { id: makeId('REQ'), ...form, quantity, requester: form.requester.trim() || 'Demo community member', resourceName, unit, location, notes: form.notes.trim(), createdAt: new Date().toISOString(), status: 'Under Review', allocatedQuantity: 0 }
    setState(current => ({ ...current, requests: [request, ...current.requests], audit: [audit(current, 'Assistance request submitted', `${request.id} · ${request.quantity} ${request.unit} ${request.resourceName}`), ...current.audit] }))
    setSelected(request.id); setShowForm(false); setMessage(`Request ${request.id} submitted. A coordinator must review it.`)
  }
  const chosen = state.requests.find(item => item.id === selected)
  const relatedReviews = chosen ? state.reviews.filter(item => item.requestId === chosen.id).reverse() : []
  const relatedDeliveries = chosen ? state.deliveries.filter(item => item.requestId === chosen.id) : []
  const activeAllocations = chosen ? state.reservations.filter(item => item.requestId === chosen.id && item.status === 'Active') : []
  const updateAllocation = (action: 'fulfill' | 'release') => {
    if (!chosen) return
    try {
      if (!fulfillmentNote.trim()) throw new Error(action === 'fulfill' ? 'Add a pickup confirmation note.' : 'Add a reason for releasing the reservation.')
      setState(current => action === 'fulfill'
        ? fulfillRequestAllocation(current, chosen.id, fulfillmentNote)
        : releaseRequestAllocation(current, chosen.id, fulfillmentNote))
      setMessage(action === 'fulfill' ? `Pickup recorded for ${chosen.id}. Inventory and fulfillment history were updated.` : `Reserved stock for ${chosen.id} was released back to available inventory.`)
      setFulfillmentNote('')
    } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not update this allocation.') }
  }
  return <div className="page-stack">
    <PageTitle title="Assistance requests" description="Submit essential needs and track their status. A coordinator reviews every allocation." action={<button className="button button--primary" onClick={() => setShowForm(value => !value)}><Plus size={16} />New request</button>} />
    <DemoStrip>Requests are simulated and saved in this browser.</DemoStrip>
    {message && <div className="inline-message" role="status">{message}</div>}
    {showForm && <section className="panel form-panel"><div className="section-head"><div><h2>Request essential resources</h2><p>Submitting a request does not promise availability or allocation.</p></div><button className="panel-close" onClick={() => setShowForm(false)} aria-label="Close form">×</button></div><form className="form-grid" onSubmit={submit}><label>Your name or organization<input value={form.requester} onChange={event => setForm({ ...form, requester: event.target.value })} placeholder="Optional" /></label><label>Resource category<select value={form.category} onChange={event => setForm({ ...form, category: event.target.value as ResourceCategory, resourceName: '' })}>{categories.map(item => <option key={item}>{item}</option>)}</select></label><label>Resource needed<input required value={form.resourceName} onChange={event => setForm({ ...form, resourceName: event.target.value })} placeholder="e.g. drinking water" /></label><label>Quantity<input required type="number" min="1" step="1" value={form.quantity} onChange={event => setForm({ ...form, quantity: event.target.value })} /></label><label>Unit<input required value={form.unit} onChange={event => setForm({ ...form, unit: event.target.value })} placeholder="litres, packs, kits…" /></label><label>Pickup area<input required minLength={2} value={form.location} onChange={event => setForm({ ...form, location: event.target.value })} placeholder="Area or landmark" /></label><label>Urgency<select value={form.urgency} onChange={event => setForm({ ...form, urgency: event.target.value as Urgency })}><option>Routine</option><option>High</option><option>Critical</option></select></label><label className="form-wide">Additional context<textarea rows={3} value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} placeholder="Optional details to help coordinators review the need" /></label><div className="form-actions"><span className="helper-text">Free assistance requests are never converted to paid orders.</span><button className="button button--primary" type="submit">Submit for review</button></div></form></section>}
    <div className="table-tools"><span>{rows.length} records</span><label><span className="sr-only">Filter by request status</span><select value={statusFilter} onChange={event => setStatusFilter(event.target.value)}><option>All statuses</option>{(['Submitted','Under Review','Partially Allocated','Approved','Fulfillment in Progress','Fulfilled','Rejected','Escalated'] as RequestStatus[]).map(item => <option key={item}>{item}</option>)}</select></label></div>
    <section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Request</th><th>Need</th><th>Location</th><th>Urgency</th><th>Status</th><th>Allocated</th></tr></thead><tbody>{rows.map(request => <tr key={request.id} className={selected === request.id ? 'selected-row' : ''} onClick={() => setSelected(selected === request.id ? null : request.id)} tabIndex={0} onKeyDown={event => { if (event.key === 'Enter') setSelected(request.id) }}><td><strong>{request.id}</strong><small>{request.requester} · {dateLabel(request.createdAt)}</small></td><td>{request.resourceName}<small>{request.quantity} {request.unit}</small></td><td>{request.location}</td><td><Badge>{request.urgency}</Badge></td><td><Badge>{request.status}</Badge></td><td>{request.allocatedQuantity} / {request.quantity} {request.unit}</td></tr>)}</tbody></table>{!rows.length && <Empty title="No requests in this status" text="Choose another status filter or submit a new request." />}</div></section>
    {chosen && <section className="panel detail-panel"><div className="section-head"><div><h2>{chosen.id} · {chosen.resourceName}</h2><p>{chosen.requester} · {chosen.location}</p></div><Badge>{chosen.status}</Badge></div><div className="detail-columns"><div><span className="detail-label">Requested</span><strong>{chosen.quantity} {chosen.unit}</strong></div><div><span className="detail-label">Allocated</span><strong>{chosen.allocatedQuantity} {chosen.unit}</strong></div><div><span className="detail-label">Still unmet</span><strong>{Math.max(0, chosen.quantity - chosen.allocatedQuantity)} {chosen.unit}</strong></div><div><span className="detail-label">Submitted</span><strong>{dateLabel(chosen.createdAt)}</strong></div></div><p className="muted">{chosen.notes || 'No additional context provided.'}</p>
      {activeAllocations.length > 0 && <section className="allocation-fulfillment"><div className="section-head compact"><div><h3>Approved stock awaiting pickup</h3><p>Confirm the handoff or release the reservation so stock can return to the marketplace.</p></div><Badge>{`${activeAllocations.reduce<number>((sum, item) => sum + item.quantity, 0)} ${chosen.unit} reserved`}</Badge></div>{activeAllocations.map(reservation => { const listing = state.listings.find(item => item.id === reservation.listingId); const warehouse = listing && getWarehouse(state, listing.warehouseId); return <div className="inventory-row" key={reservation.id}><div><strong>{listing?.name || 'Reserved resource'}</strong><small>{warehouse?.name || 'Pickup location'}{warehouse && warehouseBlocked(state, warehouse.id) ? ' · Flood blocked' : ''}</small></div><strong>{reservation.quantity} {chosen.unit}</strong></div> })}<label className="reason-field">Pickup confirmation or release reason<textarea rows={2} value={fulfillmentNote} onChange={event => setFulfillmentNote(event.target.value)} placeholder="For example: recipient collected the approved supplies" /></label><div className="review-actions"><button className="button button--secondary" onClick={() => updateAllocation('release')}>Release reservation</button><button className="button button--primary" onClick={() => updateAllocation('fulfill')}>Confirm pickup completed</button></div><p className="helper-text">This local demo action records a simulated handoff. It does not confirm a real-world delivery.</p></section>}
      <div className="section-head compact"><div><h3>Request history</h3><p>Coordinator actions and reasons.</p></div><Link className="text-link" to="/reviews">Open review workspace <ArrowRight size={14} /></Link></div>{relatedReviews.length ? relatedReviews.map(review => <div className="review-history" key={review.id}><Badge>{review.decision}</Badge><span>{review.reason}</span><small>{review.coordinator} · {dateLabel(review.createdAt)}</small></div>) : <p className="helper-text">No coordinator decision has been recorded yet.</p>}{relatedDeliveries.length > 0 && <><div className="section-head compact"><div><h3>Fulfillment history</h3><p>Simulated pickup confirmations recorded for this request.</p></div></div>{relatedDeliveries.map(delivery => <div className="inventory-row" key={delivery.id}><div><strong>{state.warehouses.find(item => item.id === delivery.warehouseId)?.name || 'Pickup location'}</strong><small>{delivery.status} · {dateLabel(delivery.updatedAt)}</small></div><strong>{delivery.quantity} {delivery.unit}</strong></div>)}</>}</section>}
  </div>
}

export function Orders() {
  const { state, setState } = useDemo()
  const [message, setMessage] = useState('')
  const updateOrder = (id: string) => {
    setState(current => {
      const order = current.orders.find(item => item.id === id)
      if (!order) return current
      const status = order.status === 'Awaiting pickup' ? 'Ready for pickup' : order.status === 'Ready for pickup' ? 'Collected' : order.status
      if (status === order.status) return current
      return { ...current, orders: current.orders.map(item => item.id === id ? { ...item, status } : item), audit: [audit(current, `Order ${status.toLowerCase()}`, `${id} · ${order.listingName} · ${order.quantity} ${order.unit}`), ...current.audit] }
    })
    setMessage('Order status updated in the local demo. This is not a real delivery confirmation.')
  }
  const orders = [...state.orders].sort((a, b) => b.createdAt.localeCompare(a.createdAt))
  return <div className="page-stack"><PageTitle title="My orders" description="Follow simulated orders from placement through pickup. No payment or delivery service is connected." action={<Link to="/resources?type=PAID" className="button button--secondary"><Store size={15} />Browse affordable goods</Link>} /><DemoStrip>Paid orders are simulated · no payment is collected</DemoStrip>{message && <div role="status" className="inline-message">{message}</div>}<section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Order</th><th>Item</th><th>Pickup location</th><th>Order total</th><th>Status</th><th>Next step</th></tr></thead><tbody>{orders.map(order => <tr key={order.id}><td><strong>{order.id}</strong><small>{dateLabel(order.createdAt)} · {order.buyer}</small></td><td>{order.listingName}<small>{order.quantity} {order.unit} × {currency(order.unitPriceInr)}</small></td><td>{order.pickupLocation}</td><td><strong>{currency(order.totalInr)}</strong></td><td><Badge>{order.status}</Badge></td><td>{order.status === 'Awaiting pickup' || order.status === 'Ready for pickup' ? <button className="button button--sm button--secondary" onClick={() => updateOrder(order.id)}>{order.status === 'Awaiting pickup' ? 'Mark ready' : 'Mark collected'}</button> : <span className="muted">Complete</span>}</td></tr>)}</tbody></table>{!orders.length && <Empty title="No orders yet" text="Affordable paid listings are separate from free assistance. You can browse surplus products when you choose." action={<Link to="/resources?type=PAID" className="button button--secondary">Browse paid listings</Link>} />}</div></section></div>
}

export function Listings() {
  const { state, setState } = useDemo()
  const [editingId, setEditingId] = useState<string | null>(null)
  const [formOpen, setFormOpen] = useState(false)
  const [error, setError] = useState('')
  const initialForm = { name: '', description: '', category: 'Water' as ResourceCategory, listingType: 'FREE' as ListingType, quantity: '1', unit: 'units', priceInr: '0', bestBefore: '', providerId: state.currentUser.organizationId, warehouseId: state.warehouses[0]?.id || '' }
  const [form, setForm] = useState(initialForm)
  const startNew = () => { setEditingId(null); setForm(initialForm); setError(''); setFormOpen(true) }
  const startEdit = (listing: ProductListing) => { setEditingId(listing.id); setForm({ name: listing.name, description: listing.description, category: listing.category, listingType: listing.listingType, quantity: String(listing.quantity), unit: listing.unit, priceInr: String(listing.priceInr), bestBefore: listing.bestBefore || '', providerId: listing.providerId, warehouseId: listing.warehouseId }); setError(''); setFormOpen(true) }
  const submit = (event: FormEvent) => {
    event.preventDefault()
    const quantity = Number(form.quantity), price = Number(form.priceInr)
    if (!Number.isInteger(quantity) || quantity < 0 || !Number.isFinite(price) || price < 0 || (form.listingType === 'PAID' && price <= 0)) { setError('Enter a non-negative whole stock quantity and a valid price. Paid listings need a price above ₹0.'); return }
    const name = form.name.trim(), unit = form.unit.trim()
    if (!name || !unit) { setError('Enter a product name and unit without leaving them blank.'); return }
    const existing = state.listings.find(item => item.id === editingId)
    if (existing && quantity < activeReservationCount(state, existing.id)) { setError(`Quantity cannot be lower than the ${activeReservationCount(state, existing.id)} units already reserved.`); return }
    if (existing && activeReservationCount(state, existing.id) > 0 && (existing.category !== form.category || existing.listingType !== form.listingType || existing.unit !== form.unit || existing.warehouseId !== form.warehouseId)) { setError('Category, listing type, unit, and pickup location cannot change while stock is reserved for a request.') ; return }
    const listing: ProductListing = { id: editingId || makeId('L'), ...form, name, unit, description: form.description.trim(), quantity, priceInr: form.listingType === 'FREE' ? 0 : price, bestBefore: form.bestBefore || undefined, createdAt: existing?.createdAt || new Date().toISOString(), status: existing?.status || 'Active' }
    setState(current => ({ ...current, listings: existing ? current.listings.map(item => item.id === editingId ? listing : item) : [listing, ...current.listings], audit: [audit(current, existing ? 'Listing updated' : 'Listing created', `${listing.name} · ${listing.quantity} ${listing.unit} · ${listing.listingType}`), ...current.audit] }))
    setFormOpen(false); setError('')
  }
  const changeListing = (listing: ProductListing, action: 'pause' | 'activate' | 'remove') => {
    if (activeReservationCount(state, listing.id) > 0 && action !== 'activate') { setError(`This listing has ${activeReservationCount(state, listing.id)} reserved units. Complete or release those allocations before changing its availability.`); return }
    const status = action === 'pause' ? 'Paused' : action === 'activate' ? 'Active' : 'Removed'
    setState(current => ({ ...current, listings: current.listings.map(item => item.id === listing.id ? { ...item, status } : item), audit: [audit(current, `Listing ${status.toLowerCase()}`, listing.name), ...current.audit] }))
  }
  return <div className="page-stack"><PageTitle title="Manage listings" description="Publish donations and affordable surplus, update stock, or pause availability." action={<button className="button button--primary" onClick={startNew}><Plus size={16} />Create listing</button>} /><DemoStrip>Inventory changes update the marketplace immediately.</DemoStrip>{error && <div role="alert" className="inline-message inline-message--error">{error}<button onClick={() => setError('')} aria-label="Dismiss">×</button></div>}
    {formOpen && <section className="panel form-panel"><div className="section-head"><div><h2>{editingId ? 'Edit listing' : 'Create a listing'}</h2><p>Free donations and paid surplus are labeled separately.</p></div><button className="panel-close" onClick={() => setFormOpen(false)} aria-label="Close form">×</button></div><form onSubmit={submit} className="form-grid"><label>Product name<input required minLength={2} value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></label><label>Category<select value={form.category} onChange={event => setForm({ ...form, category: event.target.value as ResourceCategory })}>{categories.map(item => <option key={item}>{item}</option>)}</select></label><label>Listing type<select value={form.listingType} onChange={event => setForm({ ...form, listingType: event.target.value as ListingType, priceInr: event.target.value === 'FREE' ? '0' : form.priceInr === '0' ? '1' : form.priceInr })}><option>FREE</option><option>PAID</option></select></label><label>Available quantity<input required type="number" min="0" step="1" value={form.quantity} onChange={event => setForm({ ...form, quantity: event.target.value })} /></label><label>Unit<input required value={form.unit} onChange={event => setForm({ ...form, unit: event.target.value })} placeholder="packs, litres, kits…" /></label><label>Price per unit (INR)<input type="number" min="0" step="1" disabled={form.listingType === 'FREE'} value={form.listingType === 'FREE' ? '0' : form.priceInr} onChange={event => setForm({ ...form, priceInr: event.target.value })} /></label><label>Best-before date (optional)<input type="date" value={form.bestBefore} onChange={event => setForm({ ...form, bestBefore: event.target.value })} /></label><label>Pickup warehouse<select value={form.warehouseId} onChange={event => setForm({ ...form, warehouseId: event.target.value })}>{state.warehouses.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Provider<select value={form.providerId} onChange={event => setForm({ ...form, providerId: event.target.value })}>{state.organizations.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="form-wide">Description<textarea rows={2} value={form.description} onChange={event => setForm({ ...form, description: event.target.value })} /></label><div className="form-actions"><span className="helper-text">Paid totals are shown before a simulated order. No payment is collected.</span><button className="button button--primary" type="submit">{editingId ? 'Save changes' : 'Publish listing'}</button></div></form></section>}
    <section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Listing</th><th>Type</th><th>Available</th><th>Reserved</th><th>Pickup</th><th>Status</th><th>Actions</th></tr></thead><tbody>{state.listings.filter(item => item.status !== 'Removed').map(listing => { const warehouse = getWarehouse(state, listing.warehouseId); const reserved = activeReservationCount(state, listing.id); const available = availableStock(state, listing); return <tr key={listing.id}><td><strong>{listing.name}</strong><small>{listing.id} · {listing.category}</small></td><td><Badge>{listing.listingType}</Badge><small>{listing.listingType === 'PAID' ? `${currency(listing.priceInr)} / ${listing.unit}` : 'No charge'}</small></td><td>{available} {listing.unit}<small>{listing.quantity} on hand · {unavailableStock(state, listing)} unavailable</small></td><td>{reserved} {listing.unit}</td><td>{warehouse?.name}</td><td><Badge>{listing.status === 'Active' && listing.bestBefore && new Date(listing.bestBefore).getTime() < Date.now() ? 'Expired' : listing.status}</Badge></td><td><div className="row-actions"><button className="button button--sm button--secondary" onClick={() => startEdit(listing)}>Edit</button><button className="button button--sm button--ghost" disabled={reserved > 0} onClick={() => changeListing(listing, listing.status === 'Active' ? 'pause' : 'activate')}>{listing.status === 'Active' ? 'Pause' : 'Reactivate'}</button><button className="button button--sm button--ghost" disabled={reserved > 0} onClick={() => changeListing(listing, 'remove')}>Remove</button></div></td></tr> })}</tbody></table></div></section>
  </div>
}

export function Warehouses() {
  const { state } = useDemo()
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState('All categories')
  const [selectedId, setSelectedId] = useState(state.warehouses[0]?.id || '')
  const filtered = state.warehouses.filter(item => `${item.name} ${item.address} ${item.city}`.toLowerCase().includes(query.toLowerCase()) && state.listings.some(listing => listing.warehouseId === item.id && listing.status !== 'Removed' && (category === 'All categories' || listing.category === category)))
  const selected = state.warehouses.find(item => item.id === selectedId)
  const inventory = selected ? state.listings.filter(item => item.warehouseId === selected.id && item.status !== 'Removed' && (category === 'All categories' || item.category === category)) : []
  return <div className="page-stack"><PageTitle title="Warehouses & relief centers" description="Check fictional pickup locations, access conditions, and inventory at each center." /><DemoStrip>Fictional demo locations · not live directions or road status</DemoStrip><div className="filter-bar warehouse-filters"><label className="search-field"><Search size={17} /><input aria-label="Search warehouses and relief centers" placeholder="Search location or center" value={query} onChange={event => setQuery(event.target.value)} /></label><label><span className="sr-only">Filter warehouse inventory by category</span><select value={category} onChange={event => setCategory(event.target.value)}><option>All categories</option>{categories.map(item => <option key={item}>{item}</option>)}</select></label><span className="filter-count">{filtered.length} centers</span></div><div className="warehouse-layout"><div className="warehouse-list">{filtered.map(warehouse => { const totals = warehouseInventory(state, warehouse); return <button key={warehouse.id} className={`warehouse-option ${selectedId === warehouse.id ? 'warehouse-option--selected' : ''}`} onClick={() => setSelectedId(warehouse.id)}><span className="warehouse-pin"><MapPin size={17} /></span><span className="warehouse-option-main"><strong>{warehouse.name}</strong><small>{warehouse.address} · {warehouse.city}</small><span className="warehouse-option-meta"><Badge>{warehouseBlocked(state, warehouse.id) ? 'Flood blocked' : warehouse.accessible ? 'Accessible' : 'Inaccessible'}</Badge><span>{totals.available} available</span></span></span></button> })}{!filtered.length && <Empty title="No centers match" text="Try another location or resource category." />}</div>{selected && <section className="panel warehouse-detail"><div className="section-head"><div><h2>{selected.name}</h2><p>{selected.address} · {selected.city}</p></div><Badge>{selected.verified ? 'Verified' : 'Verification pending'}</Badge></div><div className="warehouse-facts"><div><span>Hours</span><strong>{selected.hours}</strong></div><div><span>Access</span><strong>{warehouseBlocked(state, selected.id) ? 'Flood blocked in active simulation' : selected.accessible ? 'Accessible in this simulation' : 'Currently unavailable'}</strong></div><div><span>Pickup notes</span><strong>{selected.accessNotes}</strong></div></div>{selected.latitude && <p className="helper-text"><ExternalLink size={14} /> Coordinates are fictional demo points; no route or live distance is provided.</p>}<div className="section-head compact"><div><h3>Inventory</h3><p>Counts are calculated from current demo listings.</p></div></div><div className="inventory-list">{inventory.map(item => { const available = availableStock(state, item); const reserved = activeReservationCount(state, item.id); return <div className="inventory-row" key={item.id}><div><strong>{item.name}</strong><small>{item.listingType === 'PAID' ? `${currency(item.priceInr)} per ${item.unit}` : 'Free donation'} · {item.category}</small></div><div><strong>{available} {item.unit}</strong><small>{reserved} reserved · {unavailableStock(state, item)} unavailable</small></div></div> })}{!inventory.length && <p className="helper-text">No matching inventory at this center.</p>}</div></section>}</div></div>
}

export function Reviews() {
  const { state, setState } = useDemo()
  const reviews = activeReviews(state)
  const [selectedId, setSelectedId] = useState('')
  const selected = reviews.find(item => item.id === selectedId) || reviews[0]
  const match = selected ? getRecommendation(state, selected) : null
  const [allocationValues, setAllocationValues] = useState<Record<string, string>>({})
  const [reason, setReason] = useState('')
  const [message, setMessage] = useState('')
  const selectedKey = selected?.id || ''
  useEffect(() => { setAllocationValues(Object.fromEntries((match?.allocations || []).map(item => [item.listingId, String(item.quantity)]))); setReason('') }, [selectedKey])
  const decided = (decision: 'Approved' | 'Rejected' | 'Escalated') => {
    if (!selected || !match) return
    try {
      const allocations: Allocation[] = Object.entries(allocationValues).map(([listingId, value]) => ({ listingId, quantity: Number(value) })).filter(item => Number.isFinite(item.quantity) && item.quantity > 0)
      setState(applyHumanDecision(state, selected.id, decision, reason, allocations))
      setMessage(`${decision} decision recorded for ${selected.id}. Inventory reservations and request status were updated.`)
      setReason(''); setSelectedId('')
    } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not save this decision.') }
  }
  const recommendations = (match?.allocations || []).map(allocation => ({ allocation, listing: state.listings.find(item => item.id === allocation.listingId) })).filter(item => item.listing)
  return <div className="page-stack"><PageTitle title="Coordinator review" description="Review transparent resource matches. Nothing is reserved until you record a decision and reason." /><DemoStrip>Rule-based suggestions · human approval required</DemoStrip>{message && <div role="status" className="inline-message">{message}</div>}
    {!selected || !match ? <section className="panel"><Empty title="No allocation waiting for review" text="New assistance requests will appear here. Existing reservations and prior decisions remain in the audit log." action={<Link className="button button--secondary" to="/requests">View assistance requests</Link>} /></section> : <div className="review-layout"><aside className="panel review-queue"><div className="section-head"><div><h2>Waiting queue</h2><p>{reviews.length} request{reviews.length === 1 ? '' : 's'} need a decision</p></div></div>{reviews.map(request => { const recommendation = getRecommendation(state, request); return <button key={request.id} className={`queue-item ${selected.id === request.id ? 'queue-item--selected' : ''}`} onClick={() => { setSelectedId(request.id); setMessage('') }}><span className="queue-item-top"><strong>{request.id}</strong><Badge>{request.urgency}</Badge></span><span>{request.resourceName}</span><small>{request.requester} · {request.location}</small><span className="queue-availability">{recommendation.availableQuantity} available · {recommendation.shortage} short</span></button> })}</aside>
      <section className="panel review-detail"><div className="section-head"><div><p className="detail-label">Assistance request · {selected.id}</p><h2>{selected.resourceName}</h2><p>{selected.requester} · {selected.location} · submitted {dateLabel(selected.createdAt)}</p></div><Badge>{selected.urgency}</Badge></div><div className="review-need"><div><span>Requested</span><strong>{Math.max(0, selected.quantity - selected.allocatedQuantity)} {selected.unit}</strong></div><div><span>Already allocated</span><strong>{selected.allocatedQuantity} {selected.unit}</strong></div><div><span>Eligible stock now</span><strong>{match.availableQuantity} {selected.unit}</strong></div><div className={match.shortage ? 'review-shortage' : ''}><span>Shortage</span><strong>{match.shortage} {selected.unit}</strong></div></div>{match.shortage > 0 && <div className="inline-message inline-message--warning"><TriangleAlert size={16} />Only {match.availableQuantity} of the remaining {selected.quantity - selected.allocatedQuantity} {selected.unit} are eligible. The shortage cannot be approved from unavailable stock.</div>}
        <div className="explanation"><h3>Why these resources are suggested</h3><ul>{match.explanations.map(line => <li key={line}>{line}</li>)}</ul></div>
        {match.alternatives.length > 0 && <div className="alternative-sources"><strong>Other accessible free providers</strong>{match.alternatives.map(id => { const alternative = state.listings.find(item => item.id === id); const warehouse = alternative && getWarehouse(state, alternative.warehouseId); return alternative ? <div key={id}><span>{getOrganization(state, alternative.providerId)} · {warehouse?.name}</span><small>{availableStock(state, alternative)} {alternative.unit} currently eligible</small></div> : null })}</div>}
        <div className="allocation-table"><div className="allocation-heading"><strong>Proposed allocation</strong><span>Actual available · reserved · status</span></div>{recommendations.length ? recommendations.map(({ allocation, listing }) => { const warehouse = getWarehouse(state, listing!.warehouseId); return <div className="allocation-row" key={listing!.id}><div><strong>{listing!.name}</strong><small>{getOrganization(state, listing!.providerId)} · {warehouse?.name}</small><small>{warehouseBlocked(state, listing!.warehouseId) ? 'Inaccessible in flood scenario' : `${availableStock(state, listing!)} available · ${activeReservationCount(state, listing!.id)} reserved`}</small></div><label>Allocate ({selected.unit})<input type="number" min="0" max={Math.min(availableStock(state, listing!), selected.quantity - selected.allocatedQuantity)} value={allocationValues[listing!.id] || ''} onChange={event => setAllocationValues(current => ({ ...current, [listing!.id]: event.target.value }))} /></label></div> }) : <p className="helper-text">No eligible free listing is available. Paid products are not proposed as a substitute.</p>}</div>
        <label className="reason-field">Decision reason<textarea rows={3} required value={reason} onChange={event => setReason(event.target.value)} placeholder="Record why this decision is appropriate" /></label><div className="review-actions"><button className="button button--danger" onClick={() => decided('Rejected')}>Reject request</button><button className="button button--secondary" onClick={() => decided('Escalated')}>Escalate</button><button className="button button--primary" disabled={!recommendations.length} onClick={() => decided('Approved')}><ShieldCheck size={16} />Approve allocation</button></div><p className="helper-text">Approving reserves only the quantity entered above. It does not mark a request fulfilled.</p>
      </section></div>}
  </div>
}

export function Simulator() {
  const { state, setState, reset } = useDemo()
  const [message, setMessage] = useState('')
  const activate = (type: 'Flood' | 'Heatwave') => { try { setState(current => makeIncident(current, type)); setMessage(`${type} scenario activated. Effects are simulated and coordinator review is still required.`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not activate scenario.') } }
  const waterStock = state.listings.filter(item => item.category === 'Water' && item.unit === 'litres' && item.listingType === 'FREE').reduce((sum, item) => sum + availableStock(state, item), 0)
  const waterDemand = pendingRequests(state).filter(item => item.category === 'Water' && item.unit === 'litres').reduce((sum, item) => sum + item.quantity - item.allocatedQuantity, 0)
  const waterGap = Math.max(0, waterDemand - waterStock)
  const blockedWarehouses = state.incidents.flatMap(item => item.blockedWarehouseIds)
  const affected = state.requests.filter(request => state.listings.some(listing => listing.category === request.category && listing.unit === request.unit && blockedWarehouses.includes(listing.warehouseId)))
  const resetAll = () => { reset(); setMessage('Baseline demo data restored: listings, requests, orders, scenarios, reviews, and audit history.'); }
  return <div className="page-stack"><PageTitle title="Resilience simulator" description="Activate a disruption and inspect the resulting access constraints, resource gaps, and review work." action={<button className="button button--secondary" onClick={resetAll}>Reset to baseline</button>} /><DemoStrip>All scenario effects are simulated</DemoStrip>{message && <div role="status" className="inline-message">{message}</div>}
    <div className="scenario-grid"><article className="scenario-card"><span className="scenario-icon scenario-icon--blue"><Droplets size={20} /></span><h2>Flood access disruption</h2><p>Block East Junction Relief Hub. Its inventory becomes unavailable for recommendations and allocation until the baseline is restored.</p><div className="scenario-effect"><span>Expected effect</span><strong>Access ↓ · unmet needs may rise</strong></div><button className="button button--secondary" disabled={state.incidents.some(item => item.type === 'Flood')} onClick={() => activate('Flood')}>{state.incidents.some(item => item.type === 'Flood') ? 'Flood active' : 'Activate flood scenario'}</button></article><article className="scenario-card"><span className="scenario-icon scenario-icon--amber"><TriangleAlert size={20} /></span><h2>Heatwave demand increase</h2><p>Add two fictional water requests to the queue. Existing stock stays unchanged; coordinators must review every allocation.</p><div className="scenario-effect"><span>Expected effect</span><strong>Water demand ↑ · shortage recalculated</strong></div><button className="button button--secondary" disabled={state.incidents.some(item => item.type === 'Heatwave')} onClick={() => activate('Heatwave')}>{state.incidents.some(item => item.type === 'Heatwave') ? 'Heatwave active' : 'Activate heatwave scenario'}</button></article></div>
    <section className="panel"><div className="section-head"><div><h2>Current simulated impact</h2><p>Calculated from the active listings, reservations, requests, and incidents.</p></div><Badge>{state.incidents.length ? `${state.incidents.length} active scenario${state.incidents.length === 1 ? '' : 's'}` : 'Baseline state'}</Badge></div><div className="impact-grid"><div><span>Accessible water</span><strong>{waterStock} litres</strong></div><div><span>Open water demand</span><strong>{waterDemand} litres</strong></div><div className={waterGap ? 'impact-alert' : ''}><span>Unmet water demand</span><strong>{waterGap} litres</strong></div><div><span>Decision queue</span><strong>{activeReviews(state).length} requests</strong></div></div>
      {state.incidents.length ? <div className="incident-list">{state.incidents.map(incident => <div className="incident-row" key={incident.id}><span className="incident-mark"><CircleAlert size={16} /></span><div><strong>{incident.label}</strong><small>Activated {dateLabel(incident.activatedAt)} · simulated</small></div><Badge>Active</Badge></div>)}</div> : <div className="quiet-state">No disruption is active. Baseline records remain unchanged.</div>}
      {affected.length > 0 && <div className="section-subblock"><h3>Requests with inventory at a blocked center</h3><div className="record-list">{affected.map(request => <div className="record-row" key={request.id}><span className="record-symbol record-symbol--amber"><MapPin size={16} /></span><span className="record-main"><strong>{request.resourceName}</strong><small>{request.id} · {request.location}</small></span><Badge>{`${getRecommendation(state, request).availableQuantity} eligible`}</Badge></div>)}</div></div>}
      {state.incidents.some(item => item.type === 'Flood') && <div className="alternative-note"><Badge>Alternative provider</Badge><span>Harbor Relief Depot has accessible drinking water in this simulation. Review its actual available quantity before allocation.</span><Link to="/warehouses" className="text-link">Check inventory <ArrowRight size={14} /></Link></div>}
    </section>
    <section className="panel"><div className="section-head"><div><h2>Needs needing human attention</h2><p>Recommendations surface alternatives; coordinators decide what can move.</p></div><Link to="/reviews" className="button button--primary"><ShieldCheck size={15} />Open review queue</Link></div>{pendingRequests(state).slice(0, 5).map(request => { const match = getRecommendation(state, request); return <div className="record-row" key={request.id}><span className="record-main"><strong>{request.id} · {request.resourceName}</strong><small>{request.requester} · {request.location}</small></span><span>{match.availableQuantity} eligible</span><Badge>{match.shortage ? `${match.shortage} short` : request.status}</Badge></div> })}</section>
  </div>
}

export function Activity() {
  const { state } = useDemo()
  const [query, setQuery] = useState('')
  const events = state.audit.filter(item => `${item.action} ${item.actor} ${item.detail}`.toLowerCase().includes(query.toLowerCase()))
  const reviews = [...state.reviews].reverse()
  return <div className="page-stack"><PageTitle title="Activity & audit log" description="A local history of human decisions and state changes in this browser." /><DemoStrip>Audit events are fictional demo records</DemoStrip><label className="search-field audit-search"><Search size={17} /><input aria-label="Search audit history" placeholder="Search actions, actors, or records" value={query} onChange={event => setQuery(event.target.value)} /></label><section className="panel"><div className="section-head"><div><h2>Activity</h2><p>{events.length} matching events · newest first</p></div></div>{events.map(item => <div className="activity-row activity-row--large" key={item.id}><span className="activity-dot"><Clock3 size={14} /></span><span><strong>{item.action}</strong><small>{item.detail}</small></span><span className="activity-actor">{item.actor}<small>{dateLabel(item.createdAt)}</small></span></div>)}{!events.length && <Empty title="No activity found" text="Try another search term." />}</section><section className="panel"><div className="section-head"><div><h2>Coordinator decisions</h2><p>Each record includes the request, final allocation, reason, actor, and timestamp.</p></div></div>{reviews.length ? reviews.map(review => { const request = state.requests.find(item => item.id === review.requestId); const units = review.finalAllocations.reduce((sum, item) => sum + item.quantity, 0); return <div className="review-history review-history--full" key={review.id}><div><Badge>{review.decision}</Badge><strong>{review.id} · {request?.id || review.requestId}</strong></div><span>{review.reason}</span><small>{review.coordinator} · {dateLabel(review.createdAt)} · {units} {request?.unit || 'units'} allocated</small></div> }) : <Empty title="No coordinator decisions yet" text="Approve, reject, or escalate a match to create a review record." action={<Link to="/reviews" className="button button--secondary">Open review queue</Link>} />}</section></div>
}

export function Settings() {
  const { state, setRole, reset } = useDemo()
  const [resetting, setResetting] = useState(false)
  const [message, setMessage] = useState('')
  return <div className="page-stack"><PageTitle title="Settings & demo reset" description="Change the demonstration role or restore the original fictional records." /><DemoStrip />{message && <div className="inline-message" role="status">{message}</div>}<section className="panel settings-panel"><div className="section-head"><div><h2>Demo role</h2><p>Role switching is for walkthroughs only. It is not login, identity verification, or access control.</p></div><Badge>{state.role}</Badge></div><div className="role-cards">{(['Taker','Giver','Coordinator','Warehouse Provider'] as const).map(role => <button key={role} className={`role-card ${state.role === role ? 'role-card--selected' : ''}`} onClick={() => { setRole(role); setMessage(`Demo role changed to ${role}. This does not sign you in.`) }}><strong>{role}</strong><span>{role === 'Taker' ? 'Browse resources and submit assistance requests.' : role === 'Giver' ? 'Create listings and view simulated orders.' : role === 'Coordinator' ? 'Review recommendations and record allocation decisions.' : 'Inspect pickup locations and manage demo inventory.'}</span>{state.role === role && <Badge>Current role</Badge>}</button>)}</div></section><section className="panel settings-panel"><div className="section-head"><div><h2>Local demo data</h2><p>Changes stay in this browser's local storage and do not sync to a server.</p></div></div><div className="settings-facts"><div><span>Listings</span><strong>{state.listings.length}</strong></div><div><span>Assistance requests</span><strong>{state.requests.length}</strong></div><div><span>Simulated orders</span><strong>{state.orders.length}</strong></div><div><span>Audit events</span><strong>{state.audit.length}</strong></div></div>{!resetting ? <button className="button button--danger" onClick={() => setResetting(true)}>Reset to baseline data</button> : <div className="reset-confirm"><span>This clears local demo changes and restores the original seeded records.</span><button className="button button--ghost" onClick={() => setResetting(false)}>Cancel</button><button className="button button--danger" onClick={() => { reset(); setResetting(false); setMessage('Baseline restored. All demo workflows are ready to run again.') }}>Confirm reset</button></div>}</section><section className="panel settings-panel"><div className="section-head"><div><h2>Backend readiness</h2><p>The frontend uses a local mock store. No API or PostgreSQL service is connected.</p></div><Badge>Mock mode</Badge></div><p className="muted">Set <code>VITE_API_BASE_URL=http://localhost:8000/api/v1</code> and implement the proposed FastAPI contracts before switching away from mock mode. The example environment file and README explain the boundary.</p><Link to="/activity" className="text-link">View local audit history <ArrowRight size={14} /></Link></section></div>
}

